import{_ as e,o,c as a,ao as n}from"./chunks/framework.DlOpO9-F.js";const h=JSON.parse('{"title":"GIFs","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/messaging/gifs.md","filePath":"generated/grindr-api/messaging/gifs.md"}'),d={name:"grindr-api/messaging/gifs.md"};function t(l,i,s,c,r,g){return o(),a("div",null,[...i[0]||(i[0]=[n('<h1 id="gifs" tabindex="-1">GIFs <a class="header-anchor" href="#gifs" aria-label="Permalink to “GIFs”">​</a></h1><p>GIPHY&#39;s own API on <code>https://api.giphy.com</code>, Grindr&#39;s official Android app key is <code>zf7gBZ531pHaTJN3ne0jDdAepsNreB2X</code>. A GIF from it is sent as a <a href="/grindr-api/messaging/messages#giphybody">GiphyBody</a>.</p><h2 id="get-trending-gifs" tabindex="-1">Get trending GIFs <a class="header-anchor" href="#get-trending-gifs" aria-label="Permalink to “Get trending GIFs”">​</a></h2><p>GIPHY&#39;s current trending GIFs. Page through them with <code>offset</code>, see <code>pagination</code> in the response; an <code>offset</code> past <code>total_count</code> answers <code>200</code> with an empty <code>data</code>. Send one with a <a href="/grindr-api/messaging/messages#giphybody">GiphyBody</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET https://api.giphy.com/v1/gifs/trending</span></span></code></pre></div><p>Query:</p><ul><li><code>api_key</code> — string, GIPHY API key</li><li><code>limit</code> — integer, number of GIFs, default <code>25</code>, at most <code>50</code> for a beta key, optional</li><li><code>offset</code> — integer, position of the first GIF in the results, default <code>0</code>, at most <code>499</code>, optional</li><li><code>rating</code> — string, highest content rating to include: <code>g</code>, <code>pg</code>, <code>pg-13</code> or <code>r</code>; every rating when omitted, optional</li></ul><p>Response:</p><ul><li><code>data</code> — array of <a href="/grindr-api/messaging/gifs#giphygif">GiphyGif</a></li><li><code>pagination</code> — <a href="/grindr-api/messaging/gifs#giphypagination">GiphyPagination</a></li><li><code>meta</code> — <a href="/grindr-api/messaging/gifs#giphymeta">GiphyMeta</a></li></ul><h2 id="search-gifs" tabindex="-1">Search GIFs <a class="header-anchor" href="#search-gifs" aria-label="Permalink to “Search GIFs”">​</a></h2><p>Searches GIPHY. Page through results with <code>offset</code>, see <code>pagination</code> in the response. Send a result with a <a href="/grindr-api/messaging/messages#giphybody">GiphyBody</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET https://api.giphy.com/v1/gifs/search</span></span></code></pre></div><p>Query:</p><ul><li><code>api_key</code> — string, GIPHY API key</li><li><code>q</code> — string, search query, at most 50 characters</li><li><code>limit</code> — integer, number of GIFs, default <code>25</code>, at most <code>50</code> for a beta key, optional</li><li><code>offset</code> — integer, position of the first GIF in the results, default <code>0</code>, at most <code>4999</code>, optional</li><li><code>rating</code> — string, highest content rating to include: <code>g</code>, <code>pg</code>, <code>pg-13</code> or <code>r</code>; every rating when omitted, optional</li><li><code>lang</code> — string, two-letter ISO 639-1 code of the language of <code>q</code>, e.g. <code>en</code>, optional</li></ul><p>Response:</p><ul><li><code>data</code> — array of <a href="/grindr-api/messaging/gifs#giphygif">GiphyGif</a></li><li><code>pagination</code> — <a href="/grindr-api/messaging/gifs#giphypagination">GiphyPagination</a></li><li><code>meta</code> — <a href="/grindr-api/messaging/gifs#giphymeta">GiphyMeta</a></li></ul><h2 id="giphyresponse" tabindex="-1">GiphyResponse <a class="header-anchor" href="#giphyresponse" aria-label="Permalink to “GiphyResponse”">​</a></h2><p>GIPHY&#39;s list response.</p><ul><li><code>data</code> — array of <a href="/grindr-api/messaging/gifs#giphygif">GiphyGif</a>, optional</li><li><code>pagination</code> — <a href="/grindr-api/messaging/gifs#giphypagination">GiphyPagination</a>, optional</li><li><code>meta</code> — <a href="/grindr-api/messaging/gifs#giphymeta">GiphyMeta</a>, optional</li></ul><h2 id="giphygif" tabindex="-1">GiphyGif <a class="header-anchor" href="#giphygif" aria-label="Permalink to “GiphyGif”">​</a></h2><p>A GIF on GIPHY.</p><ul><li><code>type</code> — string, <code>gif</code>, optional</li><li><code>id</code> — string, GIPHY GIF ID, the <code>id</code> of a <a href="/grindr-api/messaging/messages#giphybody">GiphyBody</a>, optional</li><li><code>url</code> — string, URL of the GIF&#39;s page on <code>giphy.com</code>, optional</li><li><code>slug</code> — string, optional</li><li><code>title</code> — string, optional</li><li><code>alt_text</code> — string, may be empty, optional</li><li><code>rating</code> — string, <code>g</code>, <code>pg</code>, <code>pg-13</code> or <code>r</code>, optional</li><li><code>username</code> — string, GIPHY channel that uploaded the GIF, may be empty, optional</li><li><code>user</code> — object, the uploading channel, optional</li><li><code>source</code> — string, may be empty, optional</li><li><code>source_tld</code> — string, may be empty, optional</li><li><code>source_post_url</code> — string, may be empty, optional</li><li><code>embed_url</code> — string, optional</li><li><code>bitly_url</code> — string, optional</li><li><code>bitly_gif_url</code> — string, optional</li><li><code>content_url</code> — string, may be empty, optional</li><li><code>import_datetime</code> — string, <code>YYYY-MM-DD HH:MM:SS</code>, optional</li><li><code>trending_datetime</code> — string, <code>YYYY-MM-DD HH:MM:SS</code>, <code>0000-00-00 00:00:00</code> when the GIF never trended, optional</li><li><code>is_sticker</code> — integer, <code>0</code> or <code>1</code>, optional</li><li><code>is_low_contrast</code> — boolean, optional</li><li><code>images</code> — <a href="/grindr-api/messaging/gifs#giphyimages">GiphyImages</a>, optional</li><li><code>analytics</code> — object with <code>onload</code>, <code>onclick</code> and <code>onsent</code>, each holding a GIPHY analytics <code>url</code>, optional</li><li><code>analytics_response_payload</code> — string, optional</li></ul><h2 id="giphyimages" tabindex="-1">GiphyImages <a class="header-anchor" href="#giphyimages" aria-label="Permalink to “GiphyImages”">​</a></h2><p>Renditions of a GIF, keyed by name.</p><ul><li><code>original</code> — object, the GIF as uploaded, see <a href="#giphyrendition">GiphyRendition</a>, optional</li><li><code>original_still</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>original_mp4</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>downsized</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>downsized_large</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>downsized_medium</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>downsized_small</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>downsized_still</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>fixed_height</code> — object, 200 pixels tall, file name <code>200.gif</code>, see <a href="#giphyrendition">GiphyRendition</a>, optional</li><li><code>fixed_height_still</code> — object, still frame of <code>fixed_height</code>, file name <code>200_s.gif</code>, see <a href="#giphyrendition">GiphyRendition</a>, optional</li><li><code>fixed_height_downsampled</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>fixed_height_small</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>fixed_height_small_still</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>fixed_width</code> — object, 200 pixels wide, file name <code>200w.gif</code>, see <a href="#giphyrendition">GiphyRendition</a>, optional</li><li><code>fixed_width_still</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>fixed_width_downsampled</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>fixed_width_small</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>fixed_width_small_still</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>looping</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>preview</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>preview_gif</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>preview_webp</code> — object, see <a href="#giphyrendition">GiphyRendition</a>, optional</li><li><code>480w_still</code> — <a href="/grindr-api/messaging/gifs#giphyrendition">GiphyRendition</a>, optional</li><li><code>hd</code> — object, see <a href="#giphyrendition">GiphyRendition</a>, optional</li><li><code>4k</code> — object, see <a href="#giphyrendition">GiphyRendition</a>, optional</li></ul><h2 id="giphyrendition" tabindex="-1">GiphyRendition <a class="header-anchor" href="#giphyrendition" aria-label="Permalink to “GiphyRendition”">​</a></h2><p>One file of a GIF. Every number is sent as a string.</p><ul><li><code>url</code> — string, URL of the GIF or still image on a GIPHY media host on video-only renditions, optional</li><li><code>width</code> — string, width in pixels as a decimal number, e.g. <code>&quot;200&quot;</code>, optional</li><li><code>height</code> — string, height in pixels as a decimal number, e.g. <code>&quot;200&quot;</code>, optional</li><li><code>size</code> — string, size of <code>url</code> in bytes as a decimal number, optional</li><li><code>mp4</code> — string, URL of an MP4 version, optional</li><li><code>mp4_size</code> — string, size of <code>mp4</code> in bytes as a decimal number, optional</li><li><code>webp</code> — string, URL of an animated WebP version, optional</li><li><code>webp_size</code> — string, size of <code>webp</code> in bytes as a decimal number, optional</li><li><code>frames</code> — string, number of frames as a decimal number, only on <code>original</code>, optional</li><li><code>hash</code> — string, only on <code>original</code>, appears to be the MD5 of its <code>url</code> file, optional</li></ul><h2 id="giphypagination" tabindex="-1">GiphyPagination <a class="header-anchor" href="#giphypagination" aria-label="Permalink to “GiphyPagination”">​</a></h2><ul><li><code>total_count</code> — integer, optional</li><li><code>count</code> — integer, number of GIFs in <code>data</code>, optional</li><li><code>offset</code> — integer, the request&#39;s <code>offset</code>, <code>0</code> when omitted, optional</li></ul><h2 id="giphymeta" tabindex="-1">GiphyMeta <a class="header-anchor" href="#giphymeta" aria-label="Permalink to “GiphyMeta”">​</a></h2><ul><li><code>status</code> — integer, HTTP status, e.g. <code>200</code>, optional</li><li><code>msg</code> — string, e.g. <code>OK</code>, optional</li><li><code>response_id</code> — string, optional</li></ul>',32)])])}const f=e(d,[["render",t]]);export{h as __pageData,f as default};
